<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Upload,Download,Search}from'lucide-vue-next';const rows=ref<any[]>([]),file=ref<File|null>(null),message=ref(''),search=ref(''),type=ref('');const cols=[{key:'document_type',label:'Tipo'},{key:'access_key',label:'Chave/Identificador'},{key:'issuer_document',label:'Emitente'},{key:'recipient_document',label:'Destinatário'},{key:'total_amount',label:'Valor'},{key:'document_level',label:'Nível'},{key:'created_at',label:'Recebido'}];async function load(){rows.value=(await api.get('/documents',{params:{search:search.value||undefined,document_type:type.value||undefined}})).data}async function upload(){if(!file.value)return;const fd=new FormData();fd.append('file',file.value);try{const{data}=await api.post('/documents/import',fd);message.value=`${data.imported.length} documento(s) importado(s)`;await load()}catch(e){message.value=errorMessage(e)}}async function download(row:any){const r=await api.get(`/documents/${row.id}/download`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=`${row.access_key}.xml`;a.click();URL.revokeObjectURL(url)}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Cofre de documentos fiscais" subtitle="NF-e, NFC-e, CT-e, MDF-e, NFS-e, eventos e arquivos originais"><label class="btn"><Upload :size="16"/>Selecionar XML/ZIP<input hidden type="file" accept=".xml,.zip" @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></label><button class="btn primary" :disabled="!file" @click="upload">Importar</button></PageHeader><div v-if="message" class="alert success">{{message}}</div><section class="panel"><div class="filter-bar"><div class="search-field"><Search :size="17"/><input v-model="search" placeholder="Pesquisar chave" @keyup.enter="load"/></div><select v-model="type" @change="load"><option value="">Todos os documentos</option><option value="nfe">NF-e</option><option value="nfce">NFC-e</option><option value="cte">CT-e</option><option value="mdfe">MDF-e</option><option value="nfse">NFS-e</option></select><button class="btn" @click="load">Filtrar</button></div><DataTable :columns="cols" :rows="rows"><template #cell-document_type="{value}"><span class="doc-type">{{value.toUpperCase()}}</span></template><template #cell-total_amount="{value}">{{value?Number(value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'—'}}</template><template #cell-document_level="{value}"><StatusBadge :status="value"/></template><template #cell-created_at="{value}">{{new Date(value).toLocaleString('pt-BR')}}</template><template #actions="{row}"><button class="icon-button" title="Baixar XML" @click="download(row)"><Download :size="17"/></button></template></DataTable></section></template>
